// ============================================================
// ÉTAPE 1 : Validation payload + idempotence
// ============================================================
const body = $input.first().json.body;

// Champs obligatoires
const required = ['nom', 'telephone', 'adresse', 'ville', 'articles'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error('VALIDATION_ERROR: champs manquants: ' + missing.join(', '));
}

// Valider articles
if (!Array.isArray(body.articles) || body.articles.length === 0) {
  throw new Error('VALIDATION_ERROR: articles vide ou invalide');
}

for (const art of body.articles) {
  if (!art.id || !art.qty || art.qty < 1) {
    throw new Error('VALIDATION_ERROR: article invalide: ' + JSON.stringify(art));
  }
}

// Générer idempotency_key
const crypto = require('crypto');
const keySource = `${body.telephone}-${JSON.stringify(body.articles)}-${body.adresse}`;
const idempotency_key = crypto.createHash('sha256').update(keySource).digest('hex').slice(0, 32);

// Générer order_uid et ref_public
const order_uid = crypto.randomUUID();
const ref_public = 'MAR-' + Date.now().toString().slice(-6);

// Normaliser téléphone
let tel = body.telephone.replace(/\s/g, '').replace(/[^+0-9]/g, '');
if (tel.startsWith('0')) tel = '+212' + tel.slice(1);
if (!tel.startsWith('+')) tel = '+212' + tel;

return [{
  json: {
    ...body,
    telephone_normalise: tel,
    idempotency_key,
    order_uid,
    ref_public,
    validated_at: new Date().toISOString()
  }
}];

// ============================================================
// ÉTAPE 2 : Vérifier stock + Recalculer prix
// ============================================================
const data = $('🛡 Valider + Idempotence').first().json;
const articles = data.articles;

// Charger products.json depuis GitHub raw
const GITHUB_RAW = `https://raw.githubusercontent.com/Maruuch/Maroua/main/data/products.json`;
const res = await $helpers.request({ url: GITHUB_RAW, json: true });
const products = res.products;

const productMap = {};
for (const p of products) productMap[p.id] = p;

let total = 0;
const lignes = [];
const stockErrors = [];

for (const art of articles) {
  const prod = productMap[art.id];
  if (!prod) {
    stockErrors.push(`Produit ID ${art.id} introuvable`);
    continue;
  }
  if (prod.stock < art.qty) {
    stockErrors.push(`${prod.name}: stock insuffisant (dispo: ${prod.stock}, demandé: ${art.qty})`);
    continue;
  }
  const sous_total = prod.price * art.qty;
  total += sous_total;
  lignes.push({
    produit_id: art.id,
    notion_id: prod.notion_id,
    nom: prod.name,
    qty: art.qty,
    prix_unitaire: prod.price,
    sous_total
  });
}

if (stockErrors.length > 0) {
  throw new Error('STOCK_ERROR: ' + stockErrors.join(' | '));
}

total += 35 ? parseInt(35) : 35;

return [{ json: { ...data, lignes, total_recalcule: total } }];

// Fusionner résultats créer/MAJ client → notion_client_id
const clientPage = $input.first().json;
const data = $('📦 Vérif stock + Prix').first().json;
return [{ json: { ...data, notion_client_id: clientPage.id } }];

// Créer une ligne par article
const commande = $input.first().json;
const data = $('🔗 Merge client_id').first().json;

const lines = data.lignes.map((ligne, idx) => ({
  line_uid: `LINE-${data.ref_public.replace('MAR-', '')}-${idx + 1}`,
  notion_commande_id: commande.id,
  notion_produit_id: ligne.notion_id,
  qty: ligne.qty,
  prix_unitaire_snapshot: ligne.prix_unitaire
}));

return lines.map(l => ({ json: l }));

// ============================================================
// ÉTAPE 3 : Décrémenter stock_publie pour chaque produit
// ============================================================
const data = $('🔗 Merge client_id').first().json;

// Charger stocks actuels depuis Notion et mettre à jour
const updates = data.lignes.map(ligne => ({
  notion_id: ligne.notion_id,
  nouveau_stock: Math.max(0, (ligne.stock_actuel || 0) - ligne.qty)
}));

return updates.map(u => ({ json: u }));

// ============================================================
// Construire message WhatsApp + emails
// ============================================================
const data = $('🔗 Merge client_id').first().json;

const lignesText = data.lignes
  .map(l => `  • ${l.nom} ×${l.qty} = ${l.sous_total} MAD`)
  .join('\n');

const whatsapp_message =
  `✨ *NOUVELLE COMMANDE MAROUA* ✨\n` +
  `━━━━━━━━━━━━━━━━━━━\n` +
  `🔖 *Réf:* ${data.ref_public}\n` +
  `📅 *Date:* ${new Date().toLocaleDateString('fr-FR')}\n\n` +
  `💎 *ARTICLES*\n${lignesText}\n` +
  `━━━━━━━━━━━━━━━━━━━\n` +
  `🚚 Livraison: 35 MAD\n` +
  `💰 *TOTAL: ${data.total_recalcule} MAD*\n` +
  `💳 Paiement à la livraison\n` +
  `━━━━━━━━━━━━━━━━━━━\n` +
  `👤 *CLIENT*\n` +
  `Nom: ${data.nom}\n` +
  `Tél: ${data.telephone_normalise}\n` +
  `Adresse: ${data.adresse}\n` +
  `Ville: ${data.ville}` +
  (data.note ? `\n📝 Note: ${data.note}` : '') +
  `\n━━━━━━━━━━━━━━━━━━━`;

const email_client_body = `
Bonjour ${data.nom},

Votre commande ${data.ref_public} a bien été confirmée.

Détail :
${data.lignes.map(l => `- ${l.nom} ×${l.qty} : ${l.sous_total} MAD`).join('\n')}

Livraison : 35 MAD
Total : ${data.total_recalcule} MAD

Mode de paiement : à la livraison
Adresse : ${data.adresse}, ${data.ville}

Nous vous contacterons pour confirmer la livraison.

Merci de votre confiance,
Maroua Jewelry
`;

return [{
  json: {
    ...data,
    whatsapp_message,
    whatsapp_url: `https://wa.me/${212600000000}?text=${encodeURIComponent(whatsapp_message)}`,
    email_client_body,
    email_client_subject: `Commande ${data.ref_public} confirmée — Maroua Jewelry`
  }
}];
